package org.apache.commons.csv;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.math.*;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CSVPrinter#println()
 */
public class CSVPrinter_println_TriageGen0Test {

    @Test
    public void testPrintlnAppendsRecordSeparator() throws IOException {
        // Arrange
        StringWriter out = new StringWriter();
        CSVFormat format = CSVFormat.DEFAULT; // Default separator is \r\n or \n depending on platform, but we check content
        CSVPrinter printer = new CSVPrinter(out, format);

        // Act
        printer.println();

        // Assert
        String expectedSeparator = format.getRecordSeparator();
        Assert.assertEquals("The record separator should be appended to the output", 
                expectedSeparator, out.toString());
    }






}

