/**
 * Unit tests for CSVPrinter#println()
 */
public class CSVPrinter_println_TriageGen0Test {



    @Test
    public void testPrintlnMultipleCalls() throws IOException {
        // Arrange
        StringWriter out = new StringWriter();
        CSVFormat format = CSVFormat.DEFAULT;
        CSVPrinter printer = new CSVPrinter(out, format);
        String separator = format.getRecordSeparator();

        // Act
        printer.println();
        printer.println();

        // Assert
        String expected = separator + separator;
        Assert.assertEquals("Multiple println calls should append the separator multiple times", 
                expected, out.toString());
    }




}

