/**
 * Unit tests for CSVPrinter#println()
 */
public class CSVPrinter_println_TriageGen0Test {





    @Test
    public void testPrintlnWithData() throws IOException {
        // Arrange
        StringWriter out = new StringWriter();
        CSVFormat format = CSVFormat.DEFAULT;
        CSVPrinter printer = new CSVPrinter(out, format);

        // Act
        printer.print("data");
        printer.println();

        // Assert
        String expectedSeparator = format.getRecordSeparator();
        Assert.assertEquals("println should append separator after existing data", 
                "data" + expectedSeparator, out.toString());
    }


}

package org.apache.commons.csv;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.math.*;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CSVPrinter#println()
 */
public class CSVPrinter_println_TriageGen0Test {







    @Test(expected = IOException.class)
    public void testPrintlnThrowsIOException() throws IOException {
        // Arrange
        // A custom Appendable that always throws IOException
        Appendable throwingAppendable = new Appendable() {
            @Override
            public Appendable append(CharSequence csq) throws IOException {
                throw new IOException("Simulated IO error");
            }

            @Override
            public Appendable append(CharSequence csq, int start, int end) throws IOException {
                throw new IOException("Simulated IO error");
            }

            @Override
            public Appendable append(char c) throws IOException {
                throw new IOException("Simulated IO error");
            }
        };

        CSVPrinter printer = new CSVPrinter(throwingAppendable, CSVFormat.DEFAULT);

        // Act
        printer.println();

        // Assert handled by expected exception
    }
}
